type Stats struct {
	mu   sync.RWMutex
	hits map[string]int
}

func (s *Stats) String() string {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fmt.Sprintf("%d keys", len(s.hits))
}

func (s *Stats) Inc(key string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if key == "" {
		return fmt.Errorf("empty key in %v", s)
	}
	s.hits[key]++
	return nil
}

func (s *Stats) Get(key string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.hits[key]
}

func (s *Stats) Total(keys ...string) int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	total := 0
	for _, k := range keys {
		total += s.Get(k)
	}
	return total
}

func (c *Customer) UpdateAge(age int) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if age < 0 {
		return fmt.Errorf("negative age for %v", c) // calls c.String()
	}
	c.age = age
	return nil
}

func (c *Customer) String() string {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return fmt.Sprintf("id=%s age=%d", c.id, c.age)
}
